// Collecter les hrefs des liens internes du menu de navigation
cy.get('nav.fr-nav .fr-nav__link, nav.fr-nav a[href], [role="navigation"] a[href]').filter(':visible').then($links => {
  const baseUrl = Cypress.config('baseUrl') || 'https://cartes.gouv.fr';
  const baseDomain = new URL(baseUrl).hostname;
  // Collecter et dédoublonner les liens internes uniquement
  const seen = new Set();
  const hrefs = [];
  $links.each((_, link) => {
    const href = link.getAttribute('href');
    if (!href || href === '#' || href === '' || href.startsWith('mailto:') || href.startsWith('tel:') || href.startsWith('javascript:') || href.startsWith('data:') || href.startsWith('vbscript:')) {
      return;
    }
    // Résoudre l'URL complète pour filtrer les liens externes
    let fullUrl;
    try {
      fullUrl = new URL(href, baseUrl);
    } catch (_unused) {
      return; // URL invalide, on ignore
    }
    // Ne garder que les liens internes (même domaine)
    if (fullUrl.hostname !== baseDomain) {
      return;
    }
    // Dédoublonner par pathname (ignorer les query/hash)
    const key = fullUrl.pathname;
    if (!seen.has(key)) {
      seen.add(key);
      hrefs.push(fullUrl.pathname);
    }
  });
  expect(hrefs.length, 'Le menu doit contenir au moins un lien interne').to.be.at.least(1);
  cy.log(`🔗 ${hrefs.length} liens internes uniques trouvés`);
  // Étape 1 : Vérifier que chaque URL répond en HTTP 200 (rapide et fiable)
  // et collecter les liens qui ne redirigent pas vers un domaine externe (ex: SSO)
  const safeHrefs = [];
  hrefs.forEach(href => {
    cy.request({
      url: href,
      timeout: 30000,
      failOnStatusCode: false
    }).then(response => {
      expect(response.status, `La page ${href} doit répondre avec un statut 2xx ou 3xx`).to.be.lessThan(400);
      // Vérifier si la réponse finale reste sur le même domaine
      const finalUrl = response.redirects ? response.redirects[response.redirects.length - 1] : null;
      const isExternal = finalUrl && !finalUrl.includes(baseDomain);
      if (!isExternal) {
        safeHrefs.push(href);
      }
    });
  });
  // Étape 2 : Visiter un lien interne (qui ne redirige pas vers un domaine externe)
  // pour vérifier le rendu complet
  cy.then(() => {
    if (safeHrefs.length === 0) {
      cy.log('⚠️ Tous les liens redirigent vers un domaine externe, rendu non vérifié');
      return;
    }
    const targetHref = safeHrefs[0];
    cy.log(`📄 Vérification du rendu complet de : ${targetHref}`);
    cy.visit(targetHref, {
      timeout: 60000,
      failOnStatusCode: false
    });
    cy.document().its('readyState').should('eq', 'complete');
    cy.get('body', {
      timeout: 15000
    }).should('be.visible');
    cy.get('h1, main, [role="main"]', {
      timeout: 15000
    }).should('exist');
  });
});
